import json,os,subprocess,shutil,stat
from pathlib import Path
units=['vivoapk-backend.service','jellyfin-pink.service','jellyfin.service','pink-iptv-backend.service','pink-vpn.service','nginx.service','postgresql.service']
paths=['/srv/projects/Vivoapk','/srv/projects/Vivoapk/source','/srv/projects/Vivoapk/.venv','/srv/projects/Vivoapk/backups','/srv/projects/pink-iptv','/srv/projects/jellyfin-server','/srv/projects/jellyfin-server/run','/root/project-secrets/VIVOAPK']
out={'purpose':'VivoAPK bootstrap strong hygiene audit','read_only':True,'secret_values_read':False,'services':{},'paths':{},'git':{},'disk':{},'actions_taken':[]}
for unit in units:
 try:
  p=subprocess.run(['/usr/bin/systemctl','show',unit,'--property=LoadState,ActiveState,SubState,FragmentPath,MemoryCurrent','--no-pager'],capture_output=True,text=True,timeout=9)
  d={}
  for line in p.stdout.splitlines():
   if '=' in line:
    k,v=line.split('=',1)
    d[k]=v if k in ('LoadState','ActiveState','SubState') else ('set' if v and v!='[not set]' else 'none')
  out['services'][unit]=d if d else {'query':'unavailable'}
 except Exception as e:out['services'][unit]={'query':type(e).__name__}
for path in paths:
 p=Path(path)
 try:
  s=os.lstat(path)
  kind='link' if stat.S_ISLNK(s.st_mode) else 'directory' if stat.S_ISDIR(s.st_mode) else 'file' if stat.S_ISREG(s.st_mode) else 'other'
  out['paths'][path]={'kind':kind}
  if kind=='directory' and path in ('/srv/projects/Vivoapk','/srv/projects/pink-iptv','/srv/projects/jellyfin-server'):
   m=subprocess.run(['/usr/bin/du','-sk','--',path],capture_output=True,text=True,timeout=14)
   out['paths'][path]['kib']=int(m.stdout.split()[0]) if m.stdout.split() else None
 except FileNotFoundError:out['paths'][path]={'kind':'absent'}
 except PermissionError:out['paths'][path]={'kind':'access-denied'}
 except Exception as e:out['paths'][path]={'kind':'error','class':type(e).__name__}
for path in ['/srv/projects/Vivoapk/source','/srv/projects/jellyfin-server']:
 try:
  if Path(path).exists():
   r=subprocess.run(['/usr/bin/git','-C',path,'rev-parse','HEAD'],capture_output=True,text=True,timeout=6)
   out['git'][path]={'sha':r.stdout.strip() if r.returncode==0 and len(r.stdout.strip())==40 else 'unavailable'}
 except Exception as e:out['git'][path]={'query':type(e).__name__}
try:
 d=shutil.disk_usage('/srv')
 out['disk']={'free_gib_rounded':round(d.free/1024**3,1),'used_gib_rounded':round(d.used/1024**3,1)}
except Exception as e:out['disk']={'error':type(e).__name__}
print(json.dumps(out,sort_keys=True),flush=True)
